    driver.get(&quot;https://testweb.com&quot;);

}

 @When(&quot;^I click on Login$&quot;)
    public void I_click_on_Login() throws Throwable {
        driver.findElement(By.xpath(&quot;//a[contains(.,'Login')]&quot;)).click();
